 void ExpandedWeaponModel(Node3D n,int weapon,bool hands){if(weapon==6){Vector3[] curve={new(0,-.55f,-.12f),new(0,-.35f,-.27f),new(0,0,-.31f),new(0,.35f,-.27f),new(0,.55f,-.12f)};for(int i=0;i<curve.Length-1;i++)Tube(n,curve[i],curve[i+1],.024f,Wood);Tube(n,curve[0],new(0,0,.12f),.003f,Cloth);Tube(n,curve[^1],new(0,0,.12f),.003f,Cloth);Tube(n,new(0,0,.18f),new(0,0,-.72f),.006f,Wood);Bevel(n,new(0,0,-.74f),new(.025f,.02f,.06f),Steel);}else{Bevel(n,new(0,0,-.12f),new(.10f,.12f,.35f),Steel);for(int sign=-1;sign<=1;sign+=2)Tube(n,new(sign*.028f,.02f,-.27f),new(sign*.028f,.02f,-.85f),.025f,Steel);Bevel(n,new(0,-.025f,.18f),new(.08f,.14f,.30f),Wood);Bevel(n,new(0,-.08f,-.08f),new(.05f,.13f,.07f),Wood);Bevel(n,new(0,-.015f,-.43f),new(.12f,.09f,.23f),Wood);}if(hands)RebuiltFirstPersonArms(n,false);}
 bool MeleeStrike(){var query=PhysicsRayQueryParameters3D.Create(camera.GlobalPosition,camera.GlobalPosition-camera.GlobalBasis.Z*2.6f);query.Exclude=new Godot.Collections.Array<Rid>{player.GetRid()};var hit=GetWorld3D().DirectSpaceState.IntersectRay(query);if(hit.Count==0||game.Stamina<8)return false;var enemy=infected.Find(e=>e.Body==hit["collider"].AsGodotObject());if(enemy==null)return false;game.Stamina-=8;enemy.Hp-=(20+game.Skills.Strength.Level*2)*(1+game.Talent("melee")*.15);enemy.Stagger=.75;game.Skills.Strength.Gain(4);BloodImpact((Vector3)hit["position"],Vector3.Up,8);ConfirmHit(false);Sound(4);Noise(12);if(enemy.Hp<=0)KillEnemy(enemy);game.Persist();return true;}
